## Why This Is Asked

Tests practical algorithm design that blends classic sorts and data-structure choices. It assesses the ability to identify run structures, select appropriate sorting strategies by run size, and implement an efficient, stable k-way merge.

## Key Concepts

- Natural monotone runs detection in O(n)
- Insertion sort for small ranges; mergesort for larger ranges
- K-way merge with a min-heap and lazy advancement
- Stability guarantees and complexity trade-offs

## Code Example

```javascript
function hybridSort(a){
  const n=a.length; 
  // 1) detect monotone runs
  const runs=[]; let i=0;
  while(i<n){
    let j=i+1;
    while(j<n && a[j-1] <= a[j]) j++;
    runs.push([i,j]);
    i=j;
  }
  // 2) sort each run
  for(const [l,r] of runs){
    if(r-l <= 32) insertionSort(a,l,r);
    else mergeSort(a,l,r);
  }
  // 3) k-way merge using a min-heap
  const heap=new MinHeap((x,y)=> x.val<y.val);
  for(let idx=0; idx<runs.length; idx++){
    const [l,r]=runs[idx];
    if(l<r) heap.push({val:a[l], pos:l, runIdx:idx});
  }
  const out=new Array(n); let k=0;
  while(!heap.isEmpty()){
    const {val,pos,runIdx}=heap.pop();
    out[k++]=val;
    const [l,r]=runs[runIdx];
    const next=pos+1;
    if(next<r) heap.push({val:a[next], pos:next, runIdx});
  }
  for(let t=0;t<n;t++) a[t]=out[t];
}

function insertionSort(a,l,r){
  for(let i=l+1;i<r;i++){
    const key=a[i]; let j=i-1;
    while(j>=l && a[j]>key){ a[j+1]=a[j]; j--; }
    a[j+1]=key;
  }
}

function mergeSort(a,l,r){
  if(r-l<=1) return;
  const m=(l+r)>>1;
  mergeSort(a,l,m); mergeSort(a,m,r);
  // merge [l,m) and [m,r)
  const left=a.slice(l,m); let i=0, j=m, t=l;
  while(i<left.length && j<r) a[t++]= left[i++]<a[j]? left[i-1]: a[j++];
  while(i<left.length) a[t++]=left[i++];
  while(j<r) a[t++]=a[j++];
}

class MinHeap{
  constructor(cmp){ this.a=[]; this.cmp=cmp||((x,y)=> x<y); }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  pop(){ if(this.a.length===0) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.sinkDown(0); } return top; }
  isEmpty(){ return this.a.length===0; }
  bubbleUp(n){ const a=this.a[n]; while(n>0){ const p=(n-1)>>1; if(this.cmp(a, this.a[p])){ this.a[n]=this.a[p]; n=p; } else break; } this.a[n]=a; }
  sinkDown(n){ const length=this.a.length; const element=this.a[n]; while(true){ let child2=(n+1)*2, child1=child2-1; let swap=null; if(child1<length){ if(this.cmp(this.a[child1], element)) swap=child1; } if(child2<length){ if(this.cmp(this.a[child2], swap===null?element:this.a[child1])) swap=child2; } if(swap===null) break; this.a[n]=this.a[swap]; n=swap; } this.a[n]=element; }
}
```

